                print(json.dumps({"job_id": latest["id"], "set": latest["set_number"], "guide": latest["guide_id"],
                    "state": latest["state"], "pages": latest["alpha_completed_pages"],
                    "mains": latest["completed_panels"], "error": latest["error"]}), flush=True)
